+
+  it('handles config change: deleted tsconfig disposes project', () => {
+    tempDir = createTempDir();
+
+    const files = writeFiles(tempDir, {
+      'tsconfig.json': tsconfigJSON(),
+      'Button.tsx': `
+        import React from 'react';
