+          const sym = checker.getSymbolAtLocation(tagName);
+          if (sym && importSymbol && sym === importSymbol) {
+            const propsType = extractPropsFromJsx(node);
+            if (propsType) {
+              result = {
+                componentRef,
+                propsType,
+                symbol: resolveAliasedSymbol(typescript, checker, sym),
